# Razync Pro brand asset derived from the user-provided official RZ monogram.
# Stored compactly to keep the Streamlit deployment self-contained.
import base64
from pathlib import Path

RZ_LOGO_B64 = """"""

def ensure_brand_assets() -> str:
    asset_dir = Path(__file__).resolve().parent / ".brand_cache"
    asset_dir.mkdir(exist_ok=True)
    logo = asset_dir / "razync-rz.jpg"
    if not logo.exists():
        logo.write_bytes(base64.b64decode(RZ_LOGO_B64))
    return str(logo)
